<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>DVD Logo Bouncer</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            width: 100vw;
            height: 100vh;
            overflow: hidden;
            background-color: #1a1a2e;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        /* The container for the DVD logo */
        .dvd-logo {
            font-size: 3rem;
            font-weight: bold;
            color: #fff;
            text-shadow: 0px 2px 4px rgba(0, 0, 0, 0.5);
            position: absolute;
            user-select: none; /* Prevents highlighting during drag */
        }

    </style>
</head>
<body>

<!-- The DVD Logo Text -->
<div id="dvdLogo" class="dvd-logo">DVD</div>

<script>
/**
 * Bouncing DVD Logo Logic
 * 
 * 1. Select the DOM element representing the logo.
 * 2. Initialize velocity components (vx, vy) to simulate straight-line travel.
 * 3. Use requestAnimationFrame for smooth animation loop.
 * 4. Update position based on current velocity.
 * 5. Check boundaries; if a wall is hit, reverse the corresponding velocity component.
 */

(function() {
    const logo = document.getElementById('dvdLogo');

    // Initial state variables
    let x = window.innerWidth / 2; // Start in the center horizontally
    let y = window.innerHeight * 0.3; // Start near the top vertically

    // Velocity: Moves diagonally downwards and to the right initially
    const vx = (Math.random() + 1) * 4; 
    const vy = -((Math.random() + 1) * 5); 

    /**
     * Updates the logo's position based on current velocity.
     */
    function updatePosition() {
        x += vx;
        y += vy;

        // Apply the new coordinates to the DOM element
        logo.style.left = `${x}px`;
        logo.style.top = `${y}px`;
    }

    /**
     * Checks if the logo has hit any of the four walls.
     * Returns a string indicating which wall was hit, or null if none.
     */
    function checkBoundaries() {
        const width  = window.innerWidth;
        const height = window.innerHeight;

        // Check Right Wall
        if (x + logo.offsetWidth >= width) {
            return 'right';
        }

        // Check Left Wall
        if (x <= 0) {
            return 'left';
        }

        // Check Bottom Wall
        if (y + logo.offsetHeight >= height) {
            return 'bottom';
        }

        // Check Top Wall
        if (y <= 0) {
            return 'top';
        }

        return null; // No wall collision detected
    }

    /**
     * Handles the bounce logic. Reverses velocity based on which wall was hit.
     */
    function handleBounce(wallHit) {
        if (wallHit === 'right' || wallHit === 'left') {
            vx *= -1; // Reverse horizontal direction
        }

        if (wallHit === 'bottom' || wallHit === 'top') {
            vy *= -1; // Reverse vertical direction
        }
    }

    /**
     * The main animation loop.
     */
    function animate() {
        updatePosition();

        const collision = checkBoundaries();

        if (collision) {
            handleBounce(collision);
        }

        // Continue the frame loop even after a bounce
        requestAnimationFrame(animate);
    }

    // Start the animation
    animate();

})();
</script>
</body>
</html>
